script:
# Server Script: Apuramento de Turmas - After Submit
# DocType: Apuramento de Turmas
# Event: After Submit

# === CONFIGURAÇÕES ===
TAMANHO_MIN = doc.tamanho_minimo or 20
TAMANHO_IDEAL = doc.tamanho_ideal or 25
TAMANHO_MAX = doc.tamanho_maximo or 30

ANO_SEGUINTE = doc.ano_lectivo_seguinte
FASE_SEGUINTE = doc.fase_seguinte
FASE_ACTUAL = doc.fase_actual
FASE_PERMANECE = doc.fase_seguinte_permanece or FASE_ACTUAL

TABLE_TURMA_LISTA = "lista_catecumenos"

# === VALIDAÇÕES BÁSICAS ===
if not ANO_SEGUINTE:
    frappe.throw("Preencha o Ano Lectivo Seguinte.")
if not FASE_SEGUINTE:
    frappe.throw("Preencha a Fase Seguinte.")
if not FASE_ACTUAL:
    frappe.throw("Preencha a Fase Actual.")
    
if not doc.ano_lectivo_actual:
    frappe.throw("Preencha o Ano Lectivo Actual.")

# === VALIDAÇÃO: Ano lectivo seguinte deve ser maior que actual ===
ano_actual_valor = doc.ano_lectivo_actual
if ano_actual_valor and ANO_SEGUINTE:
    try:
        if int(ANO_SEGUINTE) <= int(ano_actual_valor):
            frappe.throw("O Ano Lectivo Seguinte (" + str(ANO_SEGUINTE) + ") deve ser maior que o Ano Lectivo Actual (" + str(ano_actual_valor) + ").")
    except ValueError:
        pass

apuramento_items = doc.get("apuramento_item") or []
if not apuramento_items:
    frappe.throw("Adicione catecúmenos à tabela de apuramento.")

apuramento_turmas = doc.get("apuramento_turmas") or []
turmas_a_processar = [t.get("turma") for t in apuramento_turmas if t.get("incluir") and t.get("turma")]

if not turmas_a_processar:
    frappe.throw("Selecione pelo menos uma turma para processar.")

# === VALIDAÇÃO: Verificar se turmas origem estão activas ===
turmas_inactivas = []
for turma_nome in turmas_a_processar:
    turma_status = frappe.db.get_value("Turma", turma_nome, "status")
    if turma_status != "Activo":
        turmas_inactivas.append(turma_nome)

if turmas_inactivas:
    frappe.throw("As seguintes turmas já não estão activas e não podem ser apuradas: " + ", ".join(turmas_inactivas))

# === VALIDAÇÃO: Verificar se turmas já foram apuradas noutro documento ===
apuramentos_existentes = frappe.db.sql("""
    SELECT DISTINCT apt.turma, ap.name
    FROM `tabApuramento Turmas Table` apt
    INNER JOIN `tabApuramento de Turmas` ap ON apt.parent = ap.name
    WHERE ap.docstatus = 1
    AND ap.name != %s
    AND apt.turma IN %s
    AND apt.incluir = 1
""", (doc.name, turmas_a_processar), as_dict=True)

if apuramentos_existentes:
    turmas_ja_apuradas = []
    for ap in apuramentos_existentes:
        turmas_ja_apuradas.append(str(ap.turma) + " (em " + str(ap.name) + ")")
    frappe.throw("As seguintes turmas já foram apuradas noutro documento: " + ", ".join(turmas_ja_apuradas))

# === VALIDAÇÃO: Verificar se todos têm resultado ===
sem_resultado = []
for item in apuramento_items:
    res = (item.get("resultado") or "").strip()
    if res not in ["Transita", "Permanece"]:
        sem_resultado.append(item.get("catecumeno"))

if sem_resultado:
    if len(sem_resultado) <= 5:
        frappe.throw("Os seguintes catecúmenos não têm resultado definido: " + ", ".join(sem_resultado))
    else:
        frappe.throw("Existem " + str(len(sem_resultado)) + " catecúmenos sem resultado definido. Defina Transita ou Permanece para todos.")

# === VALIDAÇÃO: Verificar catecúmenos duplicados na lista ===
catecumenos_lista = [item.get("catecumeno") for item in apuramento_items if item.get("catecumeno")]
catecumenos_duplicados = []
catecumenos_vistos = set()
for cat in catecumenos_lista:
    if cat in catecumenos_vistos:
        if cat not in catecumenos_duplicados:
            catecumenos_duplicados.append(cat)
    else:
        catecumenos_vistos.add(cat)

if catecumenos_duplicados:
    frappe.throw("Os seguintes catecúmenos aparecem mais de uma vez na lista: " + ", ".join(catecumenos_duplicados[:5]))

# === VALIDAÇÃO: Verificar se catecúmenos já foram apurados noutro documento do mesmo ano ===
catecumenos_ja_apurados = frappe.db.sql("""
    SELECT DISTINCT ai.catecumeno, ap.name
    FROM `tabApuramento Item` ai
    INNER JOIN `tabApuramento de Turmas` ap ON ai.parent = ap.name
    WHERE ap.docstatus = 1
    AND ap.name != %s
    AND ap.ano_lectivo_actual = %s
    AND ai.catecumeno IN %s
""", (doc.name, doc.ano_lectivo_actual, catecumenos_lista), as_dict=True)

if catecumenos_ja_apurados:
    duplicados_info = []
    for item in catecumenos_ja_apurados[:5]:
        duplicados_info.append(str(item.catecumeno) + " (em " + str(item.name) + ")")
    
    msg = "Os seguintes catecúmenos já foram apurados noutro documento deste ano lectivo: " + ", ".join(duplicados_info)
    if len(catecumenos_ja_apurados) > 5:
        msg = msg + " e mais " + str(len(catecumenos_ja_apurados) - 5) + " outros."
    frappe.throw(msg)

# === OBTER OPÇÕES DE JUNTAR (usando frappe.parse_json) ===
opcoes_juntar = {}
try:
    opcoes_str = doc.get("opcoes_juntar") or "{}"
    opcoes_juntar = frappe.parse_json(opcoes_str)
    if not opcoes_juntar:
        opcoes_juntar = {}
except Exception:
    opcoes_juntar = {}

# === SEPARAR POR RESULTADO ===
transitam = []
permanecem = []

for item in apuramento_items:
    resultado = (item.get("resultado") or "").strip()
    status = (item.get("status") or "").lower()
    
    if status in ["inactivo", "inativo", "desistente"]:
        continue
    
    cat_data = {
        "catecumeno": item.get("catecumeno"),
        "encarregado": item.get("encarregado"),
        "contacto": item.get("contacto"),
        "data_de_nascimento": item.get("data_de_nascimento"),
        "idade": item.get("idade"),
        "sexo": item.get("sexo"),
        "status": item.get("status") or "Activo",
        "turma_origem": item.get("turma_nome")
    }
    
    if resultado == "Transita":
        transitam.append(cat_data)
    elif resultado == "Permanece":
        permanecem.append(cat_data)

# === FUNÇÃO PARA OBTER CATECÚMENOS DE TURMAS EXISTENTES ===
def obter_catecumenos_turmas(turmas_nomes):
    todos = []
    for turma_nome in turmas_nomes:
        turma_doc = frappe.get_doc("Turma", turma_nome)
        lista = turma_doc.get(TABLE_TURMA_LISTA) or []
        
        for cat in lista:
            catecumeno_id = cat.get("catecumeno")
            if not catecumeno_id:
                continue
            
            status = cat.get("status") or "Activo"
            status_lower = status.lower()
            
            if status_lower in ["inactivo", "inativo", "desistente"]:
                continue
            
            todos.append({
                "catecumeno": catecumeno_id,
                "encarregado": cat.get("encarregado"),
                "contacto": cat.get("contacto"),
                "data_de_nascimento": cat.get("data_de_nascimento"),
                "idade": cat.get("idade"),
                "sexo": cat.get("sexo"),
                "status": status,
                "turma_origem": turma_nome
            })
    
    return todos

# === FUNÇÃO PARA DISTRIBUIR ===
def distribuir_em_turmas(catecumenos, tamanho_min, tamanho_ideal, tamanho_max):
    if not catecumenos:
        return []
    
    catecumenos = sorted(catecumenos, key=lambda x: x.get("catecumeno") or "")
    
    total = len(catecumenos)
    
    if total <= tamanho_max:
        num_turmas = 1
    else:
        num_turmas = (total + tamanho_ideal - 1) // tamanho_ideal
        
        while num_turmas > 1:
            media = total // num_turmas
            if media >= tamanho_min:
                break
            num_turmas = num_turmas - 1
    
    novas_turmas = []
    for i in range(num_turmas):
        novas_turmas.append({
            "numero": i + 1,
            "catecumenos": [],
            "origens": []
        })
    
    for idx, cat in enumerate(catecumenos):
        turma_idx = idx % num_turmas
        novas_turmas[turma_idx]["catecumenos"].append(cat)
        origem = cat.get("turma_origem")
        if origem and origem not in novas_turmas[turma_idx]["origens"]:
            novas_turmas[turma_idx]["origens"].append(origem)
    
    return novas_turmas

# === PROCESSAR TRANSITAM ===
turmas_a_inactivar = []
turmas_criadas = []

opcao_transitam = opcoes_juntar.get("transitam") or {}
accao_transitam = opcao_transitam.get("accao") or "criar"

if transitam:
    catecumenos_para_distribuir = transitam[:]
    
    if accao_transitam == "juntar":
        turmas_existentes = opcao_transitam.get("turmas") or []
        if turmas_existentes:
            catecumenos_existentes = obter_catecumenos_turmas(turmas_existentes)
            catecumenos_para_distribuir.extend(catecumenos_existentes)
            turmas_a_inactivar.extend(turmas_existentes)
    
    turmas_transitam = distribuir_em_turmas(catecumenos_para_distribuir, TAMANHO_MIN, TAMANHO_IDEAL, TAMANHO_MAX)
    
    for turma_data in turmas_transitam:
        if not turma_data["catecumenos"]:
            continue
        
        nova_turma = frappe.new_doc("Turma")
        nova_turma.ano_lectivo = ANO_SEGUINTE
        nova_turma.fase = FASE_SEGUINTE
        nova_turma.status = "Activo"
        nova_turma.nome = str(ANO_SEGUINTE) + " " + str(FASE_SEGUINTE) + " T" + str(turma_data["numero"])
        
        nova_turma.insert(ignore_permissions=True)
        
        catecumenos_ordenados = sorted(turma_data["catecumenos"], key=lambda x: x.get("catecumeno") or "")
        
        for cat in catecumenos_ordenados:
            nova_turma.append(TABLE_TURMA_LISTA, {
                "catecumeno": cat.get("catecumeno"),
                "encarregado": cat.get("encarregado"),
                "status": "Activo",
                "contacto": cat.get("contacto"),
                "data_de_nascimento": cat.get("data_de_nascimento"),
                "idade": cat.get("idade"),
                "sexo": cat.get("sexo")
            })
            
            frappe.db.set_value("Catecumeno", cat.get("catecumeno"), {
                "status": "Activo",
                "turma": nova_turma.name,
                "fase": FASE_SEGUINTE
            })
        
        nova_turma.save(ignore_permissions=True)
        
        turmas_criadas.append({
            "turma": nova_turma.name,
            "total_catecumenos": len(turma_data["catecumenos"]),
            "turmas_origem": ", ".join(sorted(turma_data["origens"]))
        })

# === PROCESSAR PERMANECEM ===
opcao_permanecem = opcoes_juntar.get("permanecem") or {}
accao_permanecem = opcao_permanecem.get("accao") or "criar"

if permanecem:
    catecumenos_para_distribuir = permanecem[:]
    
    if accao_permanecem == "juntar":
        turmas_existentes = opcao_permanecem.get("turmas") or []
        if turmas_existentes:
            catecumenos_existentes = obter_catecumenos_turmas(turmas_existentes)
            catecumenos_para_distribuir.extend(catecumenos_existentes)
            turmas_a_inactivar.extend(turmas_existentes)
    
    turmas_permanecem = distribuir_em_turmas(catecumenos_para_distribuir, TAMANHO_MIN, TAMANHO_IDEAL, TAMANHO_MAX)
    
    for turma_data in turmas_permanecem:
        if not turma_data["catecumenos"]:
            continue
        
        nova_turma = frappe.new_doc("Turma")
        nova_turma.ano_lectivo = ANO_SEGUINTE
        nova_turma.fase = FASE_PERMANECE
        nova_turma.status = "Activo"
        nova_turma.nome = str(ANO_SEGUINTE) + " " + str(FASE_PERMANECE) + " P" + str(turma_data["numero"])
        
        nova_turma.insert(ignore_permissions=True)
        
        catecumenos_ordenados = sorted(turma_data["catecumenos"], key=lambda x: x.get("catecumeno") or "")
        
        for cat in catecumenos_ordenados:
            nova_turma.append(TABLE_TURMA_LISTA, {
                "catecumeno": cat.get("catecumeno"),
                "encarregado": cat.get("encarregado"),
                "status": cat.get("status") or "Activo",
                "contacto": cat.get("contacto"),
                "data_de_nascimento": cat.get("data_de_nascimento"),
                "idade": cat.get("idade"),
                "sexo": cat.get("sexo")
            })
            
            frappe.db.set_value("Catecumeno", cat.get("catecumeno"), {
                "status": cat.get("status") or "Activo",
                "turma": nova_turma.name,
                "fase": FASE_PERMANECE
            })
        
        nova_turma.save(ignore_permissions=True)
        
        turmas_criadas.append({
            "turma": nova_turma.name,
            "total_catecumenos": len(turma_data["catecumenos"]),
            "turmas_origem": ", ".join(sorted(turma_data["origens"]))
        })

# === REGISTAR TURMAS CRIADAS ===
for tc in turmas_criadas:
    doc.append("apuramento_novas_turmas", tc)

# === INACTIVAR TURMAS ANTIGAS ===
for t in doc.get("apuramento_turmas") or []:
    if t.get("incluir") and t.get("turma"):
        if t.get("turma") not in turmas_a_inactivar:
            turmas_a_inactivar.append(t.get("turma"))

for turma_nome in turmas_a_inactivar:
    frappe.db.set_value("Turma", turma_nome, "status", "Inativo")

# === MENSAGEM FINAL ===
msg = "Apuramento concluído! Criadas " + str(len(turmas_criadas)) + " turma(s)."

if accao_transitam == "juntar" or accao_permanecem == "juntar":
    msg = msg + " Turmas existentes foram combinadas."

frappe.msgprint(msg)

# Corre apenas para Eucaristia
if doc.sacramento == "Eucaristia":

    rows = [r for r in doc.candidatos_sacramento_table if r.catecumeno]
    updated = 0

    for row in rows:
        frappe.db.set_value(
            "Catecumeno",
            row.catecumeno,
            {
                "eucaristia": 1,
                "data_da_eucaristia": doc.data_do_sacramento
            }
        )
        updated = updated + 1

    frappe.msgprint(
        f"Concluído: {updated} catecúmeno(s) receberam a Eucaristia "
        f"em {doc.data_do_sacramento}."
    )

today = frappe.utils.getdate(frappe.utils.nowdate())

catecumenos = frappe.get_all("Catecumeno", fields=["name", "data_de_nascimento", "idade"])

for c in catecumenos:
    if not c.data_de_nascimento:
        continue

    birth = frappe.utils.getdate(c.data_de_nascimento)

    idade_calculada = today.year - birth.year
    if (today.month, today.day) < (birth.month, birth.day):
        idade_calculada = idade_calculada - 1

    if c.idade != idade_calculada:
        frappe.db.set_value("Catecumeno", c.name, "idade", idade_calculada)

sacramento_map = {
    "Baptismo":   {"check": "baptismo",   "date": "data_do_baptismo"},
    "Eucaristia": {"check": "eucaristia", "date": "data_da_eucaristia"},
    "Crisma":     {"check": "crisma",     "date": "data_do_crisma"},
}

cfg = sacramento_map.get(doc.sacramento)

# Só corre para Eucaristia e Crisma
if cfg and doc.sacramento == "eucaristia":
    check_field = cfg["check"]
    date_field = cfg["date"]

    rows = [r for r in doc.candidatos_sacramento_table if r.catecumeno]
    updated = 0

    for row in rows:
        frappe.db.set_value("Catecumeno", row.catecumeno, {
            check_field: 1,
            date_field: doc.data_do_sacramento
        })
        updated = updated + 1  # safe_exec friendly

    frappe.msgprint(
        f"Concluído: {updated} catecúmeno(s) actualizados — {doc.sacramento} ({doc.data_do_sacramento})."
    )

# Server Script: Catecumeno - After Save
# DocType: Catecumeno
# Event: After Save

# ── 1. Turma Catecumenos ──────────────────────────────────────────────────────
try:
    if doc.turma:
        turma_status = frappe.db.get_value("Turma", doc.turma, "status")

        if turma_status == "Activo":
            child_name = frappe.db.get_value(
                "Turma Catecumenos",
                {"parent": doc.turma, "catecumeno": doc.name},
                "name"
            )

            if child_name:
                frappe.db.set_value("Turma Catecumenos", child_name, {
                    "catecumeno":         doc.name,
                    "ficha_de_catecumeno": doc.get("ficha_de_catecumeno"),
                    "encarregado":        doc.get("encarregado"),
                    "contacto":           doc.get("contacto"),
                    "padrinhos":          doc.get("padrinhos"),
                    "contacto_padrinhos": doc.get("contacto_padrinhos"),
                    "data_de_nascimento": doc.get("data_de_nascimento"),
                    "idade":              doc.get("idade")
                })

except Exception as e:
    frappe.log_error(str(e), "sync_to_turma error")


# ── 2. Candidatos ao Sacramento ───────────────────────────────────────────────
try:
    child_rows = frappe.db.get_all(
        "Candidatos ao Sacramento Table",
        filters = {"catecumeno": doc.name},
        fields  = ["name", "parent"],
        limit   = 50
    )

    for row in child_rows:
        docstatus = frappe.db.get_value("Preparacao do Sacramento", row.parent, "docstatus")
        if docstatus == 2:
            continue

        frappe.db.set_value("Candidatos ao Sacramento Table", row.name, {
            "catecumeno":          doc.name,
            "encarregado":         doc.get("encarregado"),
            "contacto_encarregado": doc.get("contacto"),
            "padrinhos":           doc.get("padrinhos"),
            "contacto_padrinhos":  doc.get("contacto_padrinhos"),
            "idade":               doc.get("idade"),
            "sexo":                doc.get("sexo")
        })

except Exception as e:
    frappe.log_error(str(e), "sync_to_sacramento error")
